import{_ as o,o as e,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const g=JSON.parse('{"title":"Popup e ícone da barra","description":"","frontmatter":{"title":"Popup e ícone da barra","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/geral/popup"}]]},"headers":[],"relativePath":"geral/popup.md","filePath":"geral/popup.md"}'),s={name:"geral/popup.md"};function n(i,a,d,p,u,l){return e(),r("div",null,a[0]||(a[0]=[t('<h1 id="popup-e-icone-da-barra" tabindex="-1">Popup e ícone da barra <a class="header-anchor" href="#popup-e-icone-da-barra" aria-label="Permalink to &quot;Popup e ícone da barra&quot;">​</a></h1><p>O ícone do eploc na barra do navegador mostra o estado da extensão e abre o <strong>popup</strong>, um painel rápido para ligar e desligar funcionalidades da página em que você está.</p><h2 id="icone-da-barra" tabindex="-1">Ícone da barra <a class="header-anchor" href="#icone-da-barra" aria-label="Permalink to &quot;Ícone da barra&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aparência</th><th>Significado</th></tr></thead><tbody><tr><td>Ícone em cinza</td><td>A extensão está desativada.</td></tr><tr><td>Ponto verde</td><td>Há funcionalidades do eploc ativas na aba atual.</td></tr><tr><td>&quot;!&quot; laranja</td><td>O backup no Google Drive precisa ser reconectado.</td></tr><tr><td>&quot;novo&quot;</td><td>Há novidades da versão instalada que você ainda não viu. Somem ao abrir a aba &quot;Novidades&quot;.</td></tr></tbody></table><h2 id="o-que-o-popup-mostra" tabindex="-1">O que o popup mostra <a class="header-anchor" href="#o-que-o-popup-mostra" aria-label="Permalink to &quot;O que o popup mostra&quot;">​</a></h2><ul><li><strong>Extensão ativa / Extensão desativada</strong>: interruptor geral. Desligado, nenhuma funcionalidade roda. Para ligar pela primeira vez, é preciso aceitar os termos de uso (o popup abre as configurações para isso).</li><li><strong>Funcionalidades nesta página</strong>: as funcionalidades que valem para a aba atual, cada uma com seu interruptor e um link para o card dela nas configurações. Um contador indica quantas estão em execução na página agora.</li><li><strong>Buscar funcionalidades...</strong>: filtra a lista pelo nome ou pela descrição.</li><li>Atalhos para <strong>Contatos salvos</strong>, <strong>Modelos de mensagem</strong>, <strong>Destaques</strong> e <strong>Processos monitorados</strong>, que abrem o gerenciador correspondente nas configurações.</li><li><strong>Configurações</strong>: abre a página de configurações.</li><li>Botão de tema: alterna entre seguir o sistema, claro e escuro.</li><li>Aviso de novidades, enquanto houver novidades da versão que você ainda não viu, com o botão <strong>Ver</strong>, que abre a aba &quot;Novidades&quot; das configurações.</li><li>Aviso de reconexão, quando a sincronização com o Google Drive para porque a conexão expirou, com o botão <strong>Reconectar</strong>.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra uma página do eproc, SEI ou RUPE.</li><li>Clique no ícone do eploc.</li><li>Ligue ou desligue funcionalidades pelos interruptores. A mudança vale na hora, sem recarregar a página.</li></ol><p>Para importar um backup, você também pode arrastar o arquivo JSON para o popup: ele abre a revisão da importação nas configurações (veja <a href="./backup-arquivo">Backup em arquivo</a>).</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O popup só lista as funcionalidades que se aplicam à página atual. Para ver todas, use a <a href="./configuracoes">página de configurações</a>.</li></ul>',11)]))}const m=o(s,[["render",n]]);export{g as __pageData,m as default};
